    59→import {OpSource} from "../../chain/validatorMonitor.js";
    60→import {Metrics} from "../../metrics/index.js";
    61→import {kzgCommitmentToVersionedHash} from "../../util/blobs.js";
    62→import {INetworkCore} from "../core/index.js";
    63→import {NetworkEvent, NetworkEventBus} from "../events.js";
    64→import {
    65→  BatchGossipHandlers,
    66→  GossipHandlerParamGeneric,
    67→  GossipHandlers,
    68→  GossipType,
    69→  SequentialGossipHandlers,
    70→} from "../gossip/interface.js";
