    76→/**
    77→ * Gossip handler options as part of network options
    78→ */
    79→export type GossipHandlerOpts = {
    80→  /** By default pass gossip attestations to forkchoice */
    81→  dontSendGossipAttestationsToForkchoice?: boolean;
    82→};
    83→
    84→export type ValidatorFnsModules = {
    85→  chain: IBeaconChain;
    86→  config: BeaconConfig;
    87→  logger: Logger;
    88→  metrics: Metrics | null;
    89→  events: NetworkEventBus;
    90→  aggregatorTracker: AggregatorTracker;
    91→  core: INetworkCore;
    92→};
    93→
    94→const MAX_UNKNOWN_BLOCK_ROOT_RETRIES = 1;
    95→const BLOCK_AVAILABILITY_CUTOFF_MS = 3_000;
    96→
    97→/**
    98→ * Gossip handlers perform validation + handling in a single function.
    99→ * - This gossip handlers MUST only be registered as validator functions. No handler is registered for any topic.
   100→ * - All `chain/validation/*` functions MUST throw typed GossipActionError instances so they gossip action is captured
   101→ *   by `getGossipValidatorFn()` try catch block.
   102→ * - This gossip handlers should not let any handling errors propagate to the caller. Only validation errors must be thrown.
   103→ *
   104→ * Note: `libp2p/js-libp2p-interfaces` would normally indicate to register separate validator functions and handler functions.
   105→ * This approach is not suitable for us because:
   106→ * - We do expensive processing on the object in the validator function that we need to re-use in the handler function.
   107→ * - The validator function produces extra data that is needed for the handler function. Making this data available in
   108→ *   the handler function scope is hard to achieve without very hacky strategies
   109→ * - Ethereum Consensus gossipsub protocol strictly defined a single topic for message
   110→ */
   111→export function getGossipHandlers(modules: ValidatorFnsModules, options: GossipHandlerOpts): GossipHandlers {
   112→  return {...getSequentialHandlers(modules, options), ...getBatchHandlers(modules, options)};
   113→}
   114→
   115→/**
   116→ * Default handlers validate gossip messages one by one.
   117→ * We only have a choice to do batch validation for beacon_attestation topic.
   118→ */
   119→function getSequentialHandlers(modules: ValidatorFnsModules, options: GossipHandlerOpts): SequentialGossipHandlers {
   120→  const {chain, config, metrics, events, logger, core} = modules;
   121→
   122→  async function validateBeaconBlock(
   123→    signedBlock: SignedBeaconBlock,
   124→    fork: ForkName,
   125→    peerIdStr: string,
   126→    seenTimestampSec: number
   127→  ): Promise<BlockInput> {
   128→    const slot = signedBlock.message.slot;
   129→    const forkTypes = config.getForkTypes(slot);
   130→    const blockRootHex = toRootHex(forkTypes.BeaconBlock.hashTreeRoot(signedBlock.message));
   131→    const blockShortHex = prettyBytes(blockRootHex);
   132→    const delaySec = chain.clock.secFromSlot(slot, seenTimestampSec);
   133→    const recvToValLatency = Date.now() / 1000 - seenTimestampSec;
   134→
   135→    // always set block to seen cache for all forks so that we don't need to download it
   136→    // TODO: validate block before adding to cache
   137→    // tracked in https://github.com/ChainSafe/lodestar/issues/7957
   138→    const blockInputRes = chain.seenGossipBlockInput.getGossipBlockInput(
   139→      config,
   140→      {
   141→        type: GossipedInputType.block,
   142→        signedBlock,
   143→      },
   144→      metrics
   145→    );
   146→    const blockInput = blockInputRes.blockInput;
   147→    // blockInput can't be returned null, improve by enforcing via return types
   148→    if (blockInput.block === null) {
   149→      throw Error(
   150→        `Invalid null blockInput returned by getGossipBlockInput for type=${GossipedInputType.block} blockHex=${blockShortHex} slot=${slot}`
   151→      );
   152→    }
   153→    const blockInputMeta =
   154→      config.getForkSeq(signedBlock.message.slot) >= ForkSeq.deneb ? blockInputRes.blockInputMeta : {};
   155→
   156→    const logCtx = {
   157→      slot: slot,
   158→      root: blockShortHex,
   159→      currentSlot: chain.clock.currentSlot,
   160→      peerId: peerIdStr,
   161→      delaySec,
   162→      ...blockInputMeta,
   163→      recvToValLatency,
   164→    };
   165→
   166→    logger.debug("Received gossip block", {...logCtx});
   167→
   168→    try {
   169→      await validateGossipBlock(config, chain, signedBlock, fork);
   170→
   171→      const recvToValidation = Date.now() / 1000 - seenTimestampSec;
   172→      const validationTime = recvToValidation - recvToValLatency;
   173→
   174→      metrics?.gossipBlock.gossipValidation.recvToValidation.observe(recvToValidation);
   175→      metrics?.gossipBlock.gossipValidation.validationTime.observe(validationTime);
   176→
   177→      logger.debug("Validated gossip block", {...logCtx, recvToValidation, validationTime});
   178→
   179→      chain.emitter.emit(routes.events.EventType.blockGossip, {slot, block: blockRootHex});
   180→
   181→      return blockInput;
   182→    } catch (e) {
   183→      if (e instanceof BlockGossipError) {
   184→        // Don't trigger this yet if full block and blobs haven't arrived yet
   185→        if (e.type.code === BlockErrorCode.PARENT_UNKNOWN && blockInput !== null) {
   186→          logger.debug("Gossip block has error", {slot, root: blockShortHex, code: e.type.code});
   187→          events.emit(NetworkEvent.unknownBlockParent, {blockInput, peer: peerIdStr});
   188→        }
   189→
   190→        if (e.action === GossipAction.REJECT) {
   191→          chain.persistInvalidSszValue(forkTypes.SignedBeaconBlock, signedBlock, `gossip_reject_slot_${slot}`);
   192→        }
   193→      }
   194→
   195→      throw e;
   196→    }
   197→  }
   198→
   199→  async function validateBeaconBlob(
   200→    blobSidecar: deneb.BlobSidecar,
   201→    subnet: SubnetID,
   202→    peerIdStr: string,
   203→    seenTimestampSec: number
   204→  ): Promise<BlockInput | NullBlockInput> {
   205→    const blobBlockHeader = blobSidecar.signedBlockHeader.message;
   206→    const slot = blobBlockHeader.slot;
   207→    const fork = config.getForkName(slot);
   208→    const blockRootHex = toRootHex(ssz.phase0.BeaconBlockHeader.hashTreeRoot(blobBlockHeader));
   209→    const blockShortHex = prettyBytes(blockRootHex);
   210→
   211→    const delaySec = chain.clock.secFromSlot(slot, seenTimestampSec);
   212→    const recvToValLatency = Date.now() / 1000 - seenTimestampSec;
   213→
   214→    try {
   215→      await validateGossipBlobSidecar(fork, chain, blobSidecar, subnet);
   216→      const {blockInput, blockInputMeta} = chain.seenGossipBlockInput.getGossipBlockInput(
   217→        config,
   218→        {
   219→          type: GossipedInputType.blob,
   220→          blobSidecar,
   221→        },
   222→        metrics
   223→      );
   224→      const recvToValidation = Date.now() / 1000 - seenTimestampSec;
   225→      const validationTime = recvToValidation - recvToValLatency;
   226→
   227→      metrics?.gossipBlob.recvToValidation.observe(recvToValidation);
   228→      metrics?.gossipBlob.validationTime.observe(validationTime);
   229→
   230→      if (chain.emitter.listenerCount(routes.events.EventType.blobSidecar)) {
   231→        chain.emitter.emit(routes.events.EventType.blobSidecar, {
   232→          blockRoot: blockRootHex,
   233→          slot,
   234→          index: blobSidecar.index,
   235→          kzgCommitment: toHex(blobSidecar.kzgCommitment),
   236→          versionedHash: toHex(kzgCommitmentToVersionedHash(blobSidecar.kzgCommitment)),
   237→        });
   238→      }
   239→
   240→      logger.debug("Received gossip blob", {
   241→        slot: slot,
   242→        root: blockShortHex,
   243→        currentSlot: chain.clock.currentSlot,
   244→        peerId: peerIdStr,
   245→        delaySec,
   246→        subnet,
   247→        ...blockInputMeta,
   248→        recvToValLatency,
   249→        recvToValidation,
   250→        validationTime,
   251→      });
   252→
   253→      return blockInput;
   254→    } catch (e) {
   255→      if (e instanceof BlobSidecarGossipError) {
   256→        // Don't trigger this yet if full block and blobs haven't arrived yet
   257→        if (e.type.code === BlobSidecarErrorCode.PARENT_UNKNOWN) {
   258→          logger.debug("Gossip blob has error", {slot, root: blockShortHex, code: e.type.code});
   259→          // no need to trigger `unknownBlockParent` event here, as we already did it in `validateBeaconBlock()`
   260→        }
   261→
   262→        if (e.action === GossipAction.REJECT) {
   263→          chain.persistInvalidSszValue(
   264→            ssz.deneb.BlobSidecar,
   265→            blobSidecar,
   266→            `gossip_reject_slot_${slot}_index_${blobSidecar.index}`
   267→          );
   268→        }
   269→      }
   270→
   271→      throw e;
   272→    }
   273→  }
   274→
   275→  async function validateBeaconDataColumn(
   276→    dataColumnSidecar: fulu.DataColumnSidecar,
   277→    dataColumnBytes: Uint8Array,
   278→    gossipSubnet: SubnetID,
   279→    peerIdStr: string,
   280→    seenTimestampSec: number
   281→  ): Promise<BlockInput | NullBlockInput> {
   282→    metrics?.peerDas.dataColumnSidecarProcessingRequests.inc();
   283→    const verificationTimer = metrics?.peerDas.dataColumnSidecarGossipVerificationTime.startTimer();
   284→
   285→    const dataColumnBlockHeader = dataColumnSidecar.signedBlockHeader.message;
   286→    const slot = dataColumnBlockHeader.slot;
   287→    const blockRootHex = toRootHex(ssz.phase0.BeaconBlockHeader.hashTreeRoot(dataColumnBlockHeader));
   288→    const blockShortHex = prettyBytes(blockRootHex);
   289→
   290→    const delaySec = chain.clock.secFromSlot(slot, seenTimestampSec);
   291→    const recvToValLatency = Date.now() / 1000 - seenTimestampSec;
   292→
   293→    try {
   294→      await validateGossipDataColumnSidecar(chain, dataColumnSidecar, gossipSubnet, metrics);
   295→      const {blockInput, blockInputMeta} = chain.seenGossipBlockInput.getGossipBlockInput(
   296→        config,
   297→        {
   298→          type: GossipedInputType.dataColumn,
   299→          dataColumnSidecar,
   300→          dataColumnBytes,
   301→        },
   302→        metrics
   303→      );
   304→
   305→      const recvToValidation = Date.now() / 1000 - seenTimestampSec;
   306→      const validationTime = recvToValidation - recvToValLatency;
   307→
   308→      metrics?.peerDas.dataColumnSidecarProcessingSuccesses.inc();
   309→      metrics?.gossipBlob.recvToValidation.observe(recvToValidation);
   310→      metrics?.gossipBlob.validationTime.observe(validationTime);
   311→
   312→      if (chain.emitter.listenerCount(routes.events.EventType.dataColumnSidecar)) {
   313→        chain.emitter.emit(routes.events.EventType.dataColumnSidecar, {
   314→          blockRoot: blockRootHex,
   315→          slot,
   316→          index: dataColumnSidecar.index,
   317→          kzgCommitments: dataColumnSidecar.kzgCommitments.map(toHex),
   318→        });
   319→      }
   320→
   321→      logger.debug("Received gossip dataColumn", {
   322→        slot: slot,
   323→        root: blockShortHex,
   324→        currentSlot: chain.clock.currentSlot,
   325→        peerId: peerIdStr,
   326→        delaySec,
   327→        gossipSubnet,
   328→        columnIndex: dataColumnSidecar.index,
   329→        ...blockInputMeta,
   330→        recvToValLatency,
   331→        recvToValidation,
   332→        validationTime,
   333→      });
   334→
   335→      return blockInput;
   336→    } catch (e) {
   337→      if (e instanceof DataColumnSidecarGossipError && e.action === GossipAction.REJECT) {
   338→        chain.persistInvalidSszValue(
   339→          ssz.fulu.DataColumnSidecar,
   340→          dataColumnSidecar,
   341→          `gossip_reject_slot_${slot}_index_${dataColumnSidecar.index}`
   342→        );
   343→        // no need to trigger `unknownBlockParent` event here, as we already did it in `validateBeaconBlock()`
   344→      }
   345→
   346→      throw e;
   347→    } finally {
   348→      verificationTimer?.();
   349→    }
   350→  }
   351→
   352→  function handleValidBeaconBlock(blockInput: BlockInput, peerIdStr: string, seenTimestampSec: number): void {
   353→    const signedBlock = blockInput.block;
   354→
   355→    // Handler - MUST NOT `await`, to allow validation result to be propagated
   356→
   357→    const delaySec = seenTimestampSec - (chain.genesisTime + signedBlock.message.slot * config.SECONDS_PER_SLOT);
   358→    metrics?.gossipBlock.elapsedTimeTillReceived.observe({source: OpSource.gossip}, delaySec);
   359→    chain.validatorMonitor?.registerBeaconBlock(OpSource.gossip, delaySec, signedBlock.message);
   360→    // if blobs are not yet fully available start an aggressive blob pull
   361→    if (blockInput.type === BlockInputType.dataPromise) {
   362→      events.emit(NetworkEvent.unknownBlockInput, {blockInput, peer: peerIdStr});
   363→    } else if (blockInput.type === BlockInputType.availableData) {
   364→      metrics?.blockInputFetchStats.totalDataAvailableBlockInputs.inc();
   365→      metrics?.blockInputFetchStats.totalDataAvailableBlockInputBlobs.inc(
   366→        (blockInput.block.message as deneb.BeaconBlock).body.blobKzgCommitments.length
   367→      );
   368→    }
   369→
   370→    chain
   371→      .processBlock(blockInput, {
   372→        // block may be downloaded and processed by UnknownBlockSync
   373→        ignoreIfKnown: true,
   374→        // proposer signature already checked in validateBeaconBlock()
   375→        validProposerSignature: true,
   376→        // blobSidecars already checked in validateGossipBlobSidecars()
   377→        validBlobSidecars: BlobSidecarValidation.Individual,
   378→        // It's critical to keep a good number of mesh peers.
   379→        // To do that, the Gossip Job Wait Time should be consistently <3s to avoid the behavior penalties in gossip
   380→        // Gossip Job Wait Time depends on the BLS Job Wait Time
   381→        // so `blsVerifyOnMainThread = true`: we want to verify signatures immediately without affecting the bls thread pool.
   382→        // otherwise we can't utilize bls thread pool capacity and Gossip Job Wait Time can't be kept low consistently.
   383→        // See https://github.com/ChainSafe/lodestar/issues/3792
   384→        blsVerifyOnMainThread: true,
   385→        // to track block process steps
   386→        seenTimestampSec,
   387→        // gossip block is validated, we want to process it asap
   388→        eagerPersistBlock: true,
   389→      })
   390→      .then(() => {
   391→        // Returns the delay between the start of `block.slot` and `current time`
   392→        const delaySec = chain.clock.secFromSlot(signedBlock.message.slot);
   393→        metrics?.gossipBlock.elapsedTimeTillProcessed.observe(delaySec);
   394→        chain.seenGossipBlockInput.prune();
   395→      })
   396→      .catch((e) => {
   397→        // Adjust verbosity based on error type
   398→        let logLevel: LogLevel;
   399→
   400→        if (e instanceof BlockError) {
   401→          switch (e.type.code) {
   402→            case BlockErrorCode.DATA_UNAVAILABLE: {
   403→              const slot = signedBlock.message.slot;
   404→              const forkTypes = config.getForkTypes(slot);
   405→              const rootHex = toRootHex(forkTypes.BeaconBlock.hashTreeRoot(signedBlock.message));
   406→
   407→              events.emit(NetworkEvent.unknownBlock, {rootHex, peer: peerIdStr});
   408→
   409→              // Error is quite frequent and not critical
   410→              logLevel = LogLevel.debug;
   411→              break;
   412→            }
   413→            // ALREADY_KNOWN should not happen with ignoreIfKnown=true above
   414→            // PARENT_UNKNOWN should not happen, we handled this in validateBeaconBlock() function above
   415→            case BlockErrorCode.ALREADY_KNOWN:
   416→            case BlockErrorCode.PARENT_UNKNOWN:
   417→            case BlockErrorCode.PRESTATE_MISSING:
   418→            case BlockErrorCode.EXECUTION_ENGINE_ERROR:
   419→              // Errors might indicate an issue with our node or the connected EL client
   420→              logLevel = LogLevel.error;
   421→              break;
   422→            default:
   423→              // TODO: Should it use PeerId or string?
   424→              core.reportPeer(peerIdStr, PeerAction.LowToleranceError, "BadGossipBlock");
   425→              // Misbehaving peer, but could highlight an issue in another client
   426→              logLevel = LogLevel.warn;
   427→          }
   428→        } else {
   429→          // Any unexpected error
   430→          logLevel = LogLevel.error;
   431→        }
   432→        metrics?.gossipBlock.processBlockErrors.inc({error: e instanceof BlockError ? e.type.code : "NOT_BLOCK_ERROR"});
   433→        logger[logLevel]("Error receiving block", {slot: signedBlock.message.slot, peer: peerIdStr}, e as Error);
   434→        chain.seenGossipBlockInput.prune();
   435→      });
   436→
   437→    if (blockInput.type === BlockInputType.dataPromise) {
   438→      const blockSlot = blockInput.block.message.slot;
   439→      // if blobs are not yet fully available start an aggressive blob pull
   440→      chain.logger.debug("Block under processing is not available, racing with cutoff to add to unknownBlockInput", {
   441→        blockSlot,
   442→      });
   443→      raceWithCutoff(
   444→        chain,
   445→        blockSlot,
   446→        blockInput.cachedData.availabilityPromise as Promise<BlockInputAvailableData>,
   447→        BLOCK_AVAILABILITY_CUTOFF_MS
   448→      ).catch((_e) => {
   449→        chain.logger.debug("Block under processing not yet available, racing with cutoff to add to unknownBlockInput", {
   450→          blockSlot,
   451→        });
   452→        events.emit(NetworkEvent.unknownBlockInput, {blockInput, peer: peerIdStr});
   453→        return null;
   454→      });
   455→    }
   456→  }
   457→
   458→  return {
   459→    [GossipType.beacon_block]: async ({
   460→      gossipData,
   461→      topic,
   462→      peerIdStr,
   463→      seenTimestampSec,
   464→    }: GossipHandlerParamGeneric<GossipType.beacon_block>) => {
   465→      const {serializedData} = gossipData;
   466→
   467→      const signedBlock = sszDeserialize(topic, serializedData);
   468→      const blockInput = await validateBeaconBlock(signedBlock, topic.boundary.fork, peerIdStr, seenTimestampSec);
   469→      chain.serializedCache.set(signedBlock, serializedData);
   470→      handleValidBeaconBlock(blockInput, peerIdStr, seenTimestampSec);
   471→    },
   472→
   473→    [GossipType.blob_sidecar]: async ({
   474→      gossipData,
   475→      topic,
   476→      peerIdStr,
   477→      seenTimestampSec,
   478→    }: GossipHandlerParamGeneric<GossipType.blob_sidecar>) => {
   479→      const {serializedData} = gossipData;
   480→      const blobSidecar = sszDeserialize(topic, serializedData);
   481→      const blobSlot = blobSidecar.signedBlockHeader.message.slot;
   482→      const index = blobSidecar.index;
   483→
   484→      if (config.getForkSeq(blobSlot) < ForkSeq.deneb) {
   485→        throw new GossipActionError(GossipAction.REJECT, {code: "PRE_DENEB_BLOCK"});
   486→      }
   487→      const blockInput = await validateBeaconBlob(blobSidecar, topic.subnet, peerIdStr, seenTimestampSec);
   488→      if (blockInput.block !== null) {
   489→        if (blockInput.type === BlockInputType.dataPromise) {
   490→          chain.logger.debug("Block corresponding to blob is available but waiting for data availability", {
   491→            blobSlot,
   492→            index,
   493→          });
   494→          await raceWithCutoff(
   495→            chain,
   496→            blobSlot,
   497→            blockInput.cachedData.availabilityPromise as Promise<BlockInputAvailableData>,
   498→            BLOCK_AVAILABILITY_CUTOFF_MS
   499→          ).catch((_e) => {
   500→            chain.logger.debug("Block under processing not yet fully available adding to unknownBlockInput", {
   501→              blobSlot,
   502→            });
   503→            events.emit(NetworkEvent.unknownBlockInput, {blockInput, peer: peerIdStr});
   504→          });
   505→        }
   506→      } else {
   507→        // wait for the block to arrive till some cutoff else emit unknownBlockInput event
   508→        chain.logger.debug("Block not yet available, racing with cutoff", {blobSlot, index});
   509→        const normalBlockInput = await raceWithCutoff(
   510→          chain,
   511→          blobSlot,
   512→          blockInput.blockInputPromise,
   513→          BLOCK_AVAILABILITY_CUTOFF_MS
   514→        ).catch((_e) => {
   515→          return null;
   516→        });
   517→
   518→        if (normalBlockInput !== null) {
   519→          // we can directly send it for processing but block gossip handler will queue it up anyway
   520→          // if we see any issues later, we can send it to handleValidBeaconBlock
   521→          //
   522→          // handleValidBeaconBlock(normalBlockInput, peerIdStr, seenTimestampSec);
   523→          //
   524→          // however we can emit the event which will atleast add the peer to the list of peers to pull
   525→          // data from
   526→          if (normalBlockInput.type === BlockInputType.dataPromise) {
   527→            chain.logger.debug("Block corresponding to blob is now available but waiting for data availability", {
   528→              blobSlot,
   529→              index,
   530→            });
   531→            await raceWithCutoff(
   532→              chain,
   533→              blobSlot,
   534→              normalBlockInput.cachedData.availabilityPromise as Promise<BlockInputAvailableData>,
   535→              BLOCK_AVAILABILITY_CUTOFF_MS
   536→            ).catch((_e) => {
   537→              chain.logger.debug("Block under processing not yet fully available adding to unknownBlockInput", {
   538→                blobSlot,
   539→              });
   540→              events.emit(NetworkEvent.unknownBlockInput, {blockInput: normalBlockInput, peer: peerIdStr});
   541→            });
   542→          } else {
   543→            chain.logger.debug("Block corresponding to blob is now available for processing", {blobSlot, index});
   544→          }
   545→        } else {
   546→          chain.logger.debug(
   547→            "Block corresponding to blob not available till BLOCK_AVAILABILITY_CUTOFF_MS adding to unknownBlockInput",
   548→            {blobSlot, index}
   549→          );
   550→          events.emit(NetworkEvent.unknownBlockInput, {blockInput, peer: peerIdStr});
   551→        }
   552→      }
   553→    },
   554→
   555→    [GossipType.data_column_sidecar]: async ({
   556→      gossipData,
   557→      topic,
   558→      peerIdStr,
   559→      seenTimestampSec,
   560→    }: GossipHandlerParamGeneric<GossipType.data_column_sidecar>) => {
   561→      const {serializedData} = gossipData;
   562→      const dataColumnSidecar = sszDeserialize(topic, serializedData);
   563→      const dataColumnSlot = dataColumnSidecar.signedBlockHeader.message.slot;
   564→      const index = dataColumnSidecar.index;
   565→
   566→      if (config.getForkSeq(dataColumnSlot) < ForkSeq.fulu) {
   567→        throw new GossipActionError(GossipAction.REJECT, {code: "PRE_FULU_BLOCK"});
   568→      }
   569→      const delaySec = chain.clock.secFromSlot(dataColumnSlot, seenTimestampSec);
   570→      metrics?.dataColumns.elapsedTimeTillReceived.observe({source: DataColumnsSource.gossip}, delaySec);
   571→      const blockInput = await validateBeaconDataColumn(
   572→        dataColumnSidecar,
   573→        serializedData,
   574→        topic.subnet,
   575→        peerIdStr,
   576→        seenTimestampSec
   577→      );
   578→      if (blockInput.block !== null) {
   579→        if (blockInput.type === BlockInputType.dataPromise) {
   580→          chain.logger.debug("Block corresponding to data column is available but waiting for data availability", {
   581→            dataColumnSlot,
   582→            index,
   583→          });
   584→          await raceWithCutoff(
   585→            chain,
   586→            dataColumnSlot,
   587→            blockInput.cachedData.availabilityPromise as Promise<BlockInputAvailableData>,
   588→            BLOCK_AVAILABILITY_CUTOFF_MS
   589→          ).catch((_e) => {
   590→            chain.logger.debug("Block under processing not yet fully available adding to unknownBlockInput", {
   591→              dataColumnSlot,
   592→            });
   593→            events.emit(NetworkEvent.unknownBlockInput, {blockInput, peer: peerIdStr});
   594→          });
   595→        }
   596→      } else {
   597→        // wait for the block to arrive till some cutoff else emit unknownBlockInput event
   598→        chain.logger.debug("Block not yet available, racing with cutoff", {dataColumnSlot, index});
   599→        const normalBlockInput = await raceWithCutoff(
   600→          chain,
   601→          dataColumnSlot,
   602→          blockInput.blockInputPromise,
   603→          BLOCK_AVAILABILITY_CUTOFF_MS
   604→        ).catch((_e) => {
   605→          return null;
   606→        });
   607→
   608→        if (normalBlockInput !== null) {
   609→          if (normalBlockInput.type === BlockInputType.dataPromise) {
   610→            chain.logger.debug(
   611→              "Block corresponding to data column is now available but waiting for data availability",
   612→              {
   613→                dataColumnSlot,
   614→                index,
   615→              }
   616→            );
   617→            await raceWithCutoff(
   618→              chain,
   619→              dataColumnSlot,
   620→              normalBlockInput.cachedData.availabilityPromise as Promise<BlockInputAvailableData>,
   621→              BLOCK_AVAILABILITY_CUTOFF_MS
   622→            ).catch((_e) => {
   623→              chain.logger.debug("Block under processing not yet fully available adding to unknownBlockInput", {
   624→                dataColumnSlot,
   625→              });
   626→              events.emit(NetworkEvent.unknownBlockInput, {blockInput: normalBlockInput, peer: peerIdStr});
   627→            });
   628→          } else {
   629→            chain.logger.debug("Block corresponding to data column is now available for processing", {
   630→              dataColumnSlot,
   631→              index,
   632→            });
   633→          }
   634→        } else {
   635→          chain.logger.debug("Block not available till BLOCK_AVAILABILITY_CUTOFF_MS", {
   636→            dataColumnSlot,
   637→            index,
   638→          });
   639→          events.emit(NetworkEvent.unknownBlockInput, {blockInput, peer: peerIdStr});
   640→        }
   641→      }
   642→    },
   643→
   644→    [GossipType.beacon_aggregate_and_proof]: async ({
   645→      gossipData,
   646→      topic,
   647→      seenTimestampSec,
   648→    }: GossipHandlerParamGeneric<GossipType.beacon_aggregate_and_proof>) => {
   649→      const {serializedData} = gossipData;
   650→      let validationResult: AggregateAndProofValidationResult;
   651→      const signedAggregateAndProof = sszDeserialize(topic, serializedData);
   652→      const {fork} = topic.boundary;
   653→
   654→      try {
   655→        validationResult = await validateGossipAggregateAndProof(fork, chain, signedAggregateAndProof, serializedData);
   656→      } catch (e) {
