   855→function getBatchHandlers(modules: ValidatorFnsModules, options: GossipHandlerOpts): BatchGossipHandlers {
   856→  const {chain, metrics, logger, aggregatorTracker} = modules;
   857→  return {
   858→    [GossipType.beacon_attestation]: async (
   859→      gossipHandlerParams: GossipHandlerParamGeneric<GossipType.beacon_attestation>[]
   860→    ): Promise<(null | AttestationError)[]> => {
   861→      const results: (null | AttestationError)[] = [];
   862→      const attestationCount = gossipHandlerParams.length;
   863→      if (attestationCount === 0) {
   864→        return results;
   865→      }
   866→      // all attestations should have same attestation data as filtered by network processor
   867→      const {fork} = gossipHandlerParams[0].topic.boundary;
   868→      const validationParams = gossipHandlerParams.map((param) => ({
   869→        attestation: null,
   870→        serializedData: param.gossipData.serializedData,
   871→        attSlot: param.gossipData.msgSlot,
   872→        attDataBase64: param.gossipData.indexed,
   873→        subnet: param.topic.subnet,
   874→      })) as GossipAttestation[];
   875→      const {results: validationResults, batchableBls} = await validateGossipAttestationsSameAttData(
   876→        fork,
   877→        chain,
   878→        validationParams
   879→      );
   880→      for (const [i, validationResult] of validationResults.entries()) {
   881→        if (validationResult.err) {
   882→          results.push(validationResult.err as AttestationError);
   883→          continue;
   884→        }
   885→        // null means no error
   886→        results.push(null);
   887→
   888→        // Handler
   889→        const {
   890→          indexedAttestation,
   891→          attDataRootHex,
   892→          attestation,
   893→          committeeIndex,
   894→          validatorCommitteeIndex,
   895→          committeeSize,
   896→        } = validationResult.result;
   897→        chain.validatorMonitor?.registerGossipUnaggregatedAttestation(
   898→          gossipHandlerParams[i].seenTimestampSec,
   899→          indexedAttestation
   900→        );
   901→
   902→        const {subnet} = validationResult.result;
   903→        try {
   904→          // Node may be subscribe to extra subnets (long-lived random subnets). For those, validate the messages
   905→          // but don't add to attestation pool, to save CPU and RAM
   906→          if (aggregatorTracker.shouldAggregate(subnet, indexedAttestation.data.slot)) {
   907→            const insertOutcome = chain.attestationPool.add(
   908→              committeeIndex,
   909→              attestation,
   910→              attDataRootHex,
   911→              validatorCommitteeIndex,
   912→              committeeSize
   913→            );
   914→            metrics?.opPool.attestationPool.gossipInsertOutcome.inc({insertOutcome});
   915→          }
   916→        } catch (e) {
   917→          logger.error("Error adding unaggregated attestation to pool", {subnet}, e as Error);
   918→        }
   919→
   920→        if (!options.dontSendGossipAttestationsToForkchoice) {
   921→          try {
   922→            chain.forkChoice.onAttestation(indexedAttestation, attDataRootHex);
   923→          } catch (e) {
   924→            logger.debug("Error adding gossip unaggregated attestation to forkchoice", {subnet}, e as Error);
   925→          }
   926→        }
   927→
   928→        if (isForkPostElectra(fork)) {
   929→          chain.emitter.emit(
   930→            routes.events.EventType.singleAttestation,
   931→            attestation as SingleAttestation<ForkPostElectra>
   932→          );
   933→        } else {
   934→          chain.emitter.emit(routes.events.EventType.attestation, attestation as SingleAttestation<ForkPreElectra>);
   935→          chain.emitter.emit(
   936→            routes.events.EventType.singleAttestation,
   937→            toElectraSingleAttestation(
   938→              attestation as SingleAttestation<ForkPreElectra>,
   939→              indexedAttestation.attestingIndices[0]
   940→            )
   941→          );
   942→        }
   943→      }
   944→
   945→      if (batchableBls) {
   946→        metrics?.gossipAttestation.attestationBatchHistogram.observe(attestationCount);
   947→      } else {
   948→        metrics?.gossipAttestation.attestationNonBatchCount.inc(attestationCount);
   949→      }
   950→
   951→      return results;
   952→    },
   953→  };
   954→}
