   956→/**
   957→ * Retry a function if it throws error code UNKNOWN_OR_PREFINALIZED_BEACON_BLOCK_ROOT
   958→ */
   959→export async function validateGossipFnRetryUnknownRoot<T>(
   960→  fn: () => Promise<T>,
   961→  network: INetwork,
   962→  chain: IBeaconChain,
   963→  slot: Slot,
   964→  blockRoot: Root
   965→): Promise<T> {
   966→  let unknownBlockRootRetries = 0;
   967→  while (true) {
   968→    try {
   969→      return await fn();
   970→    } catch (e) {
   971→      if (
   972→        e instanceof AttestationError &&
   973→        e.type.code === AttestationErrorCode.UNKNOWN_OR_PREFINALIZED_BEACON_BLOCK_ROOT
   974→      ) {
   975→        if (unknownBlockRootRetries === 0) {
   976→          // Trigger unknown block root search here
   977→          const rootHex = toRootHex(blockRoot);
   978→          network.searchUnknownSlotRoot({slot, root: rootHex});
   979→        }
   980→
   981→        if (unknownBlockRootRetries++ < MAX_UNKNOWN_BLOCK_ROOT_RETRIES) {
   982→          const foundBlock = await chain.waitForBlock(slot, toRootHex(blockRoot));
   983→          // Returns true if the block was found on time. In that case, try to get it from the fork-choice again.
   984→          // Otherwise, throw the error below.
   985→          if (foundBlock) {
   986→            continue;
   987→          }
   988→        }
   989→      }
   990→
   991→      throw e;
   992→    }
   993→  }
   994→}
   995→
   996→async function raceWithCutoff<T>(
   997→  chain: {config: ChainForkConfig; genesisTime: UintNum64; logger: Logger},
   998→  blockSlot: Slot,
   999→  availabilityPromise: Promise<T>,
  1000→  cutoffMsFromSlotStart: number
  1001→): Promise<T> {
  1002→  const cutoffTimeMs = Math.max(
  1003→    computeTimeAtSlot(chain.config, blockSlot, chain.genesisTime) * 1000 + cutoffMsFromSlotStart - Date.now(),
  1004→    0
  1005→  );
  1006→  const cutoffTimeout = new Promise((_resolve, reject) => setTimeout(reject, cutoffTimeMs));
  1007→  await Promise.race([availabilityPromise, cutoffTimeout]);
  1008→  // we can only be here if availabilityPromise has resolved else an error will be thrown
  1009→  return availabilityPromise;
  1010→}
